  const box = document.querySelector('.el-message-box')
  const overlay = document.querySelector('.el-overlay')
  const wrap = document.querySelector('.el-overlay-message-box')
  const pick = (el) => {
    if (!el) return null
    const r = el.getBoundingClientRect()
    const cs = getComputedStyle(el)
    return {
      tag: el.className,
      rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
      display: cs.display, visibility: cs.visibility, opacity: cs.opacity,
      zIndex: cs.zIndex, position: cs.position, transform: cs.transform,
      overflow: cs.overflow,
    }
  }
  const buttons = [...document.querySelectorAll('.el-message-box button')].map((b) => {
    const r = b.getBoundingClientRect()
    const cs = getComputedStyle(b)
    const cx = r.x + r.width / 2, cy = r.y + r.height / 2
    const top = document.elementFromPoint(cx, cy)
    return {
      text: b.textContent.trim(),
      rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
      display: cs.display, visibility: cs.visibility, pointerEvents: cs.pointerEvents,
      topElementAtCenter: top ? `${top.tagName}.${top.className}` : null,
      reachable: !!top && (top === b || b.contains(top)),
    }
  })
  const vw = innerWidth, vh = innerHeight
  return {
    viewport: { vw, vh },
    scroll: { x: scrollX, y: scrollY },
    box: pick(box), overlay: pick(overlay), wrap: pick(wrap),
    buttons,
    bodyOverflow: getComputedStyle(document.body).overflow,
    dialogText: box?.textContent?.trim().slice(0, 200) ?? null,
  }
})
