{"command": "cd /home/zhaodan/work/NodeJsProjects/agent-hub-web && cat > repro-dom.mjs <<'EOF'
import { chromium } from '@playwright/test'
const browser = await chromium.launch({ args: ['--no-proxy-server'] })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('http://127.0.0.1:5173/login')
await page.getByPlaceholder('you@example.com').fill('admin@example.com')
await page.getByPlaceholder('至少 8 位').fill('12345678')
await page.getByRole('button', { name: '登录', exact: true }).click()
await page.waitForURL(/\/chat/)
await page.goto('http://127.0.0.1:5173/settings')
await page.waitForTimeout(500)
await page.addStyleTag({ path: 'node_modules/element-plus/theme-chalk/el-message-box.css' })
await page.addStyleTag({ path: 'node_modules/element-plus/theme-chalk/el-button.css' })
await page.getByRole('button', { name: '退出登录' }).click()
await page.waitForTimeout(500)
const info = await page.evaluate(() => {
  const overlays = [...document.querySelectorAll('.el-overlay')].map((el) => {
    const r = el.getBoundingClientRect()
    const cs = getComputedStyle(el)
    return {
      cls: el.className,
      display: cs.display, visibility: cs.visibility, opacity: cs.opacity,
      zIndex: cs.zIndex, position: cs.position, background: cs.backgroundColor,
      rect: { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) },
    }
  })
  const bodyChildren = [...document.body.children].map((el) => {
    const cs = getComputedStyle(el)
    return { tag: el.tagName, cls: el.className, display: cs.display }
  })
  const mb = document.querySelector('.el-message-box')
  let p = mb
  const chain = []
  while (p && chain.length < 6) {
    const cs = getComputedStyle(p)
    chain.push({ tag: p.tagName, cls: p.className, display: cs.display, position: cs.position, zIndex: cs.zIndex, bg: cs.backgroundColor, opacity: cs.opacity })
    p = p.parentElement
  }
  return { overlays, bodyChildren, chain }
})
console.log(JSON.stringify(info, null, 2))
await browser.close()
