  const box = document.querySelector('.el-message-box')
  const overlay = document.querySelector('.el-overlay.is-message-box')
  const r = box?.getBoundingClientRect()
  const or = overlay?.getBoundingClientRect()
  const buttons = [...document.querySelectorAll('.el-message-box button')].map((b) => {
    const br = b.getBoundingClientRect()
    return { text: b.textContent.trim(), w: Math.round(br.width), h: Math.round(br.height) }
  })
  return {
    box: r
