          position: getComputedStyle(box).position,
        }
      : null,
    overlay: or
      ? {
          w: Math.round(or.width),
          h: Math.round(or.height),
          display: getComputedStyle(overlay).display,
          bg: getComputedStyle(overlay).backgroundColor,
        }
      : null,
    buttons,
  }
})
